/* oxlint-disable typescript/strict-boolean-expressions -- Normalizer patterns and AST fixture nodes are untyped generated-source data. */
const GENERATOR_DIRECTIVE =
  /^\s*(?:\/\/\s*@ts-nocheck\b.*|\/\*\s*(?:eslint-disable(?:\s+[^*]*)?|prettier-ignore)\s*\*\/|\/\/\s*(?:eslint|prettier|biome)-disable\b.*)\r?\n?/gmu;

const GENERATED_TYPECHECK_OPT_OUT =
  "// @ts-nocheck -- generated by @napi-rs/cli";
const ARTIFACT_METADATA_PREFIX =
  "// napi-rs-artifact-metadata:";

const SAFE_SCHEDULER_HELPER = `function __invokeWasmCleanupPollScheduler(schedule, settle, reject) {
  let finishedDuringScheduling = false
  let scheduling = true
  const finish = () => {
    if (scheduling) {
      finishedDuringScheduling = true
      return
    }
    settle()
  }
  try {
    schedule(finish)
  } catch (error) {
    reject(error)
    return
  }
  scheduling = false
  if (finishedDuringScheduling) {
    settle()
  }
}

`;

const RUNTIME_POLL_MARKER =
  "/**\n * One turn of the runtime-work poll.";

const UNSAFE_CLEANUP_HANDSHAKE = `await new Promise((resolve) => {
        __scheduleMacrotask(resolve)
      })`;

const LEGACY_SAFE_CLEANUP_HANDSHAKE = `await new Promise((resolve, reject) => {
        let finishedDuringScheduling = false
        let scheduling = true
        const finish = () => {
          if (scheduling) {
            finishedDuringScheduling = true
            return
          }
          resolve()
        }
        try {
          __scheduleMacrotask(finish)
        } catch (error) {
          reject(error)
          return
        }
        scheduling = false
        if (finishedDuringScheduling) {
          resolve()
        }
      })`;

const SAFE_CLEANUP_HANDSHAKE = `await new Promise((resolve, reject) => {
        __invokeWasmCleanupPollScheduler(
          __scheduleMacrotask,
          resolve,
          reject,
        )
      })`;

const UNSAFE_RUNTIME_POLL_PROMISE = `return new Promise((resolve) => {
    let settled = false`;

const SAFE_RUNTIME_POLL_PROMISE = `return new Promise((resolve, reject) => {
    let settled = false`;

const UNSAFE_RUNTIME_POLL_TIMER = `__scheduleTimer(() => {
      pace.arrivals++
      settle()
    }, __WASM_RUNTIME_WORK_POLL_INTERVAL_MS)`;

const SAFE_RUNTIME_POLL_TIMER = `__invokeWasmCleanupPollScheduler(
      (finish) => {
        __scheduleTimer(() => {
          pace.arrivals++
          finish()
        }, __WASM_RUNTIME_WORK_POLL_INTERVAL_MS)
      },
      settle,
      reject,
    )`;

const UNSAFE_RUNTIME_POLL_SCHEDULE = `let finishedDuringScheduling = false
      let scheduling = true
      const finish = () => {
        if (scheduling) {
          finishedDuringScheduling = true
          return
        }
        settle()
      }
      try {
        __scheduleMacrotask(finish)
      } catch (error) {
        reject(error)
        return
      }
      scheduling = false
      if (finishedDuringScheduling) {
        settle()
      }
      return`;

const UNSAFE_DIRECT_RUNTIME_POLL_SCHEDULE = `__scheduleMacrotask(settle)
      return`;

const SAFE_RUNTIME_POLL_SCHEDULE = `__invokeWasmCleanupPollScheduler(
        __scheduleMacrotask,
        settle,
        reject,
      )
      return`;

const RETRYABLE_RUNTIME_CLEANUP =
  /\}\)\(\)\.then\((finishCleanup(?:UnlessCrashed)?), \1\)/gu;

const makeRuntimeCleanupRetryable = (
  _match,
  finishCleanup,
) => `})().then(
    ${finishCleanup},
    (error) => {
      __emnapiWasmEnvCleanupPreparing = false
      throw error
    },
  )`;

const addTypecheckHeader = (source) => {
  if (!source.startsWith(ARTIFACT_METADATA_PREFIX)) {
    return `${GENERATED_TYPECHECK_OPT_OUT}\n${source}`;
  }
  const lineEnd = source.indexOf("\n");
  if (lineEnd < 0) {
    return `${source}\n${GENERATED_TYPECHECK_OPT_OUT}\n`;
  }
  return `${source.slice(0, lineEnd + 1)}${GENERATED_TYPECHECK_OPT_OUT}\n${source.slice(lineEnd + 1)}`;
};

/** Normalize directives and cleanup scheduling emitted by the NAPI generator. */
export const normalizeGeneratedLoader = (
  source,
  { keepGeneratedTypecheckOptOut = false } = {},
) => {
  const normalized = source
    .replace(GENERATOR_DIRECTIVE, "")
    .replaceAll(
      UNSAFE_CLEANUP_HANDSHAKE,
      SAFE_CLEANUP_HANDSHAKE,
    )
    .replaceAll(
      LEGACY_SAFE_CLEANUP_HANDSHAKE,
      SAFE_CLEANUP_HANDSHAKE,
    )
    .replace(
      UNSAFE_RUNTIME_POLL_PROMISE,
      SAFE_RUNTIME_POLL_PROMISE,
    )
    .replace(
      UNSAFE_RUNTIME_POLL_TIMER,
      SAFE_RUNTIME_POLL_TIMER,
    )
    .replace(
      UNSAFE_RUNTIME_POLL_SCHEDULE,
      SAFE_RUNTIME_POLL_SCHEDULE,
    )
    .replace(
      UNSAFE_DIRECT_RUNTIME_POLL_SCHEDULE,
      SAFE_RUNTIME_POLL_SCHEDULE,
    )
    .replace(
      RETRYABLE_RUNTIME_CLEANUP,
      makeRuntimeCleanupRetryable,
    )
    .replace(/[ \t]+$/gmu, "");

  const withSchedulerHelper = normalized.includes(
    "function __invokeWasmCleanupPollScheduler(",
  )
    ? normalized
    : normalized.replace(
        RUNTIME_POLL_MARKER,
        `${SAFE_SCHEDULER_HELPER}${RUNTIME_POLL_MARKER}`,
      );

  return keepGeneratedTypecheckOptOut
    ? addTypecheckHeader(withSchedulerHelper)
    : withSchedulerHelper;
};
